WITH unpacked AS (SELECT id, log_ts, latency_ms, status_code, payload_json, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, context['region'] AS region, context['version'] AS version, SIZE(context) AS num_context, COALESCE(context['region'], 'unknown') AS region_or_default FROM app_logs WHERE log_ts >= '2024-07-13') SELECT *, SUM(num_context) OVER (ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_num_context, RANK() OVER (ORDER BY num_context NULLS FIRST) AS num_context_rank, LAG(status_code, 1) OVER (ORDER BY log_ts, id) AS prev_status_code, ROW_NUMBER() OVER (ORDER BY log_ts, id) AS row_seq, NTILE(10) OVER (ORDER BY latency_ms, id) AS latency_ms_bucket FROM unpacked;
